SOQL Where Clause:
((gr_period_of_performance_star__c !=  NULL
            AND gr_period_of_performance_curr__c = NULL
        )
        OR (gr_period_of_performance_star__c = NULL
            AND gr_period_of_performance_curr__c != NULL
        ))

gr_record_type__c IN ('1', '2')
    AND ( (gr_place_of_perform_country_c__c = 'USA'
                AND gr_place_of_performance_code__c = '00FORGN'
               )
        OR (gr_place_of_perform_country_c__c <> 'USA'
            AND gr_place_of_performance_code__c <> '00FORGN'
        )
    )
    AND gr_correction_delete_indicatr__c <> 'D'
